let clinicalDB={};try{clinicalDB=JSON.parse(localStorage.getItem(REG_PRIVATE_KEY)||'{}')||{}}catch(e){clinicalDB={}};
function clinicalGet(pid){if(!clinicalDB[pid])clinicalDB[pid]={risk:[],milestones:[],screens:[],notes:[],rawLabs:[],deliveryNotes:''};return clinicalDB[pid]}
function clinicalSave(){try{localStorage.setItem(REG_PRIVATE_KEY,JSON.stringify(clinicalDB))}catch(e){}}
function regAudit(action,pid){save(session?.name||'Демо эмч',action,pid);clinicalSave()}
function regG(p){p.labs=Array.isArray(p.labs)?p.labs:[];p.carePlan=Array.isArray(p.carePlan)?p.carePlan:[];p.trainingPublic=Array.isArray(p.trainingPublic)?p.trainingPublic:[];p.postpartumFollowups=Array.isArray(p.postpartumFollowups)?p.postpartumFollowups:[];return p;}
function regTag(txt,klass=''){return `<span class="rg-tag ${klass}">${h(txt)}</span>`}
function regTitle(t,sub=''){return `<div class="rg-title"><div><h2>${h(t)}</h2>${sub?`<p>${h(sub)}</p>`:''}</div><span class="rg-source">ЭМС журам · 2024</span></div>`}
function regField(label,name,val='',type='text',req=false){return `<label class="rg-field"><span>${h(label)} ${req?'*':''}</span><input name="${name}" type="${type}" value="${h(val)}" ${req?'required':''}></label>`}
function regText(label,name='',val='',req=false){return `<label class="rg-field rg-full"><span>${h(label)}</span><textarea name="${name}" ${req?'required':''}>${h(val)}</textarea></label>`}
function regChoice(label,name,opts,cur='',req=false){return `<label class="rg-field"><span>${h(label)}</span><select name="${name}" ${req?'required':''}>${opts.map(([v,t])=>`<option value="${h(v)}" ${cur===v?'selected':''}>${h(t)}</option>`).join('')}</select></label>`}
function regSubmit(text='Хадгалах'){return `<div class="rg-footer"><button class="primary" type="submit">✓ ${h(text)}</button></div>`}
function regSummary(p){regG(p);const c=clinicalGet(p.id),done=p.carePlan.filter(x=>x.status==='complete').length, labs=p.labs.filter(x=>x.status!=='reviewed').length,post=p.postpartumFollowups.length;return `<div class="rg-counters"><div><small>8 үзлэгийн checklist</small><b>${done}/8</b></div><div><small>Шинжилгээ хүлээгдэж буй</small><b>${labs}</b></div><div><small>Эрсдэлийн үнэлгээ</small><b>${c.risk.length}</b></div><div><small>Төрсний дараах үзлэг</small><b>${post}/4</b></div></div>`}
function regMilestoneTab(p){
 regG(p);
 const all=V19_PROTOCOL_STEPS.map((s,i)=>({s,i,stats:v19Stats(p,i)}));
 const totalSelf=all.reduce((n,x)=>n+x.stats.self,0);
 const totalTasks=all.reduce((n,x)=>n+x.stats.total,0);
 const cards=all.map(({s,i,stats})=>{
    const status=stats.self?`<span class="v20-status confirmed">${stats.self}/${stats.total}</span>`:`<span class="v20-status none">Тэмдэглээгүй</span>`;
    return `<button type="button" class="v20-timeline-item ${stats.self?'needs-review':''}" data-v20-open="${i}" aria-label="№${i+1} ${h(s.title)} үзлэгийн тэмдэглэгээг харах"><span class="v20-stage-num">${i+1}</span><span class="v20-stage-text"><strong>№${i+1} · ${h(i===0?'Анхны хяналт':s.title)} · ${h(s.period)}</strong><small>${stats.self} тэмдэглэсэн · ${stats.pending} дутуу · Нийт ${stats.total}</small></span>${status}<span class="v20-caret">›</span></button>`;
 }).join('');
 return `<div class="v20-protocol-hub"><div class="v20-hub-header"><div><div class="kicker">ХАВСРАЛТ 2 · 8 ҮЗЛЭГ</div><h2>Хяналтын явц</h2><p>Үзлэгийн мөр дээр дарахад тухайн эхийн тэмдэглэсэн болон дутуу шинжилгээ, үзлэгүүд харагдана.</p></div></div><div class="v20-mini-counters" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div><small>Тэмдэглэсэн</small><b>${totalSelf}</b></div><div><small>Дутуу</small><b>${totalTasks-totalSelf}</b></div></div><div class="v20-timeline-list">${cards}</div></div>`;
}
function regChecklistHTML(index){return `<div class="rg-checklist"><b>Энэ үед үнэлэх зүйлс</b>${(REG_STEPS[Number(index)]?.list||[]).map((txt,j)=>`<label><input type="checkbox" name="check" value="${j}"><span>${h(txt)}</span></label>`).join('')}</div>`}
function regRiskTab(p){const c=clinicalGet(p.id),last=c.risk.slice(-1)[0];return `${regTitle('А / Б / В / Г эрсдэлийн хүчин зүйлс','Хавсралт 3 · Эмчийн дотоод үнэлгээ. A/B/C байгууллагын хуучин ангилалтай хольж болохгүй.')}
 <div class="rg-alert">🔒 Энэ асуумж, илэрсэн эрсдэл, дүгнэлт зөвхөн эмчийн интерфейст харагдана. Эхийн аппд автоматаар нийтлэхгүй.</div><div class="rg-box"><form id="regRiskForm" class="rg-form">${regField('Үнэлгээний огноо','date',today(),'date',true)}<div class="rg-risk-grids">${Object.entries(REG_RISK).map(([letter,items])=>`<section><h3>${letter} бүлэг · ${({A:'Нийгэм, биологийн хүчин зүйл',Б:'Эх барихын ужиг дурдатгал',В:'Эрхтэн тогтолцооны эмгэг',Г:'Одоогийн жирэмсний хүндрэл'})[letter]}</h3>${items.map((txt,i)=>`<label class="rg-risk-item"><input type="checkbox" name="riskFactor" value="${h(letter+'|'+i)}"><span>${h(txt)}</span></label>`).join('')}</section>`).join('')}</div>${regText('Илэрсэн хүчин зүйлийн талаарх эмчийн дүгнэлт','note','',true)}${regText('Нарийн мэргэжлийн эмчтэй хамтарсан хяналтын төлөвлөгөө','plan')}${regSubmit('Эрсдэлийн үнэлгээ хадгалах')}</form></div>${last?`<div class="rg-box"><h3>Сүүлийн үнэлгээ · ${pretty(last.date)}</h3><p>${last.factors.length} хүчин зүйл тэмдэглэсэн · ${h(last.note)}</p>${last.plan?`<p><b>Хяналтын төлөвлөгөө:</b> ${h(last.plan)}</p>`:''}</div>`:''}`}
function regLabsTab(p){regG(p);return `${regTitle('Шинжилгээний цахим бүртгэл','Хавсралт 2 · захиалсан → өгсөн → хариу гарсан → эмч үнэлсэн.')}<div class="rg-box"><h3>Шинжилгээ бүртгэх</h3><form id="regLabForm" class="rg-form rg-grid">${regChoice('Шинжилгээний төрөл','name',[['Цусны ерөнхий шинжилгээ','Цусны ерөнхий шинжилгээ'],['Шээсний ерөнхий шинжилгээ','Шээсний ерөнхий шинжилгээ'],['ЭХО','ЭХО'],['Сахарын сорил','Сахарын сорил'],['Халдвар илрүүлэх шинжилгээ','Халдвар илрүүлэх шинжилгээ'],['В бүлгийн стрептококк','В бүлгийн стрептококк'],['Бусад','Бусад']])}${regField('Огноо','date',today(),'date',true)}${regChoice('Төлөв','status',[['ordered','Захиалсан'],['collected','Сорьц өгсөн'],['result','Хариу ирсэн, эмч хараахан үнэлээгүй'],['reviewed','Эмч үнэлж, эхэд тайлбар бэлэн']])}${regText('Дотоод лабораторийн хариу, тоон үзүүлэлт (зөвхөн эмчид)','rawResult')}${regText('Эхэд харуулах тайлбар','message')}${regSubmit('Шинжилгээний бүртгэл нэмэх')}</form></div><div class="rg-box"><h3>Шинжилгээний бүртгэлийн түүх (${p.labs.length})</h3>${p.labs.length?p.labs.slice().reverse().map(x=>`<div class="rg-record"><div><b>${h(x.name)}</b><small>${pretty(x.date)}</small><p>${h(x.message||'Эмчийн тайлбар хүлээгдэж байна.')}</p></div>${regTag(({ordered:'Захиалсан',collected:'Сорьц өгсөн',result:'Эмчийн үнэлгээ хүлээж буй',reviewed:'Эмч үнэлсэн'})[x.status]||x.status,x.status==='reviewed'?'good':'')}</div>`).join(''):'<p class="rg-muted">Бүртгэл хараахан байхгүй.</p>'}</div>`}
function regScreenTab(p){const c=clinicalGet(p.id);return `${regTitle('Тусгай илрүүлэлтийн асуумж','Хавсралт 3 · сүрьеэ, хүчирхийлэл; хавсралт 4 · Эдинбургийн сорил.')}
 <div class="rg-alert">🔒 Хүчирхийллийн асуумжийг аюулгүй, хувийн нөхцөлд авна. Эхийн утасны апп, мэдэгдэл, ердийн LOG-т хариу болон шалгалт хийснийг ч нийтлэхгүй.</div><div class="rg-box"><h3>Сүрьеэгийн 8 асуулт · анхны хяналт, 20 ба 32 долоо хоног</h3><form id="regTBForm" class="rg-form">${regField('Авсан өдөр','date',today(),'date',true)}${REG_TB.map((q,i)=>`<label class="rg-question"><span>${i+1}. ${h(q)}</span><select name="tb${i}" required><option value="">— Хариулаагүй —</option><option value="no">Үгүй</option><option value="yes">Тийм</option></select></label>`).join('')}${regText('Мэргэжлийн эмчид илгээсэн шийдвэр, тэмдэглэл','note')}${regSubmit('Сүрьеэгийн асуумж хадгалах')}</form></div>
 <div class="rg-box"><h3>Хүчирхийлэл илрүүлэх асуумж · анх, 24, 36 долоо хоног, төрсний дараах 7–14 хоног</h3><form id="regDVForm" class="rg-form">${regField('Авсан өдөр','date',today(),'date',true)}${REG_DV.map((q,i)=>`<label class="rg-question"><span>${i+1}. ${h(q)}</span><select name="dv${i}" required><option value="">— Хариулаагүй —</option><option value="no">Үгүй</option><option value="yes">Тийм</option></select></label>`).join('')}${regText('Нууц үнэлгээ, эрсдэлийн хамгаалалтын төлөвлөгөө','note')}${regSubmit('Нууц асуумж хадгалах')}</form></div>
 <div class="rg-box"><h3>Эдинбургийн төрсний дараах сэтгэл гутралын сорил</h3><p class="rg-muted">Төрсний дараах эхний 7 хоног; журмын дагуу нийт ≥11 бол мэргэжлийн тусламжид илгээх, 5–9 эсвэл өөрийгөө гэмтээх бодол илэрвэл давтан/яаралтай үнэлгээ хийх шаардлагатай. Энд оноог автоматаар онош гэж үзэхгүй.</p><form id="regEPDSForm" class="rg-form">${regField('Үнэлсэн өдөр','date',today(),'date',true)}${REG_EPDS.map((q,i)=>`<label class="rg-question"><span>${i+1}. ${h(q)}</span><select name="ep${i}" required><option value="">— Оноо —</option>${[0,1,2,3].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></label>`).join('')}${regText('Эмчийн дүгнэлт, тусламжийн төлөвлөгөө','note')}${regSubmit('Эдинбургийн сорил хадгалах')}</form></div>
 <div class="rg-box"><h3>Нууц үнэлгээний түүх</h3>${c.screens.length?c.screens.slice().reverse().map(s=>`<div class="rg-record"><div><b>${({tb:'Сүрьеэгийн асуумж',dv:'Хүчирхийлэл илрүүлэлт',epds:'Эдинбургийн сорил'})[s.type]}</b><small>${pretty(s.date)} · ${h(s.note||'Тэмдэглэлгүй')}</small></div>${regTag(s.type==='epds'?s.score+'/30':s.positive+' эерэг',s.positive?'warn':'')}</div>`).join(''):'<p class="rg-muted">Үнэлгээний бүртгэл байхгүй.</p>'}</div>`}
function regDeliveryTab(p){regG(p);const has=Boolean(p.delivery?.date);let momPlan='';if(has){momPlan=REG_POST.map(([code,title])=>{let f=p.postpartumFollowups.find(x=>x.code===code);return `<div class="rg-step"><span class="rg-step-num ${f?'rg-done':''}">${f?'✓':'○'}</span><div><b>${title}</b><small>${f?pretty(f.date)+' · Хийгдсэн':'Товлогдоогүй / дутуу'}</small></div></div>`}).join('')}
 return `${regTitle('Төрөлт ба төрсний дараах хяналт','Хавсралт 2 · эхний 24 цаг, 48–72 цаг, 7–14 хоног, 5–6 долоо хоног.')}
 <div class="rg-split"><div class="rg-box"><h3>Төрөлтийн бүртгэл</h3><form id="regDeliveryForm" class="rg-form">${regField('Төрсөн огноо','date',p.delivery?.date||today(),'date',true)}${regField('Төрсөн байгууллага','place',p.delivery?.place||'')}${regChoice('Төрөлтийн хэлбэр','type',[['','— Сонгох —'],['normal','Үтрээгээр'],['cesarean','Кесар мэс засал'],['other','Бусад']],p.delivery?.type||'')}${regText('Эхэд харагдах төрсний дараах зөвлөгөө','message',p.delivery?.message||'')}${regText('Дотоод төрөлтийн тэмдэглэл','privateNote')}${regSubmit('Төрөлт хадгалах')}</form></div><div class="rg-box"><h3>Төрсний дараах 4 удаагийн хяналт</h3>${has?momPlan:'<p class="rg-muted">Төрөлтийн бүртгэл хийсний дараа хяналтын бүртгэл нээгдэнэ.</p>'}${has?`<form id="regPostForm" class="rg-form">${regChoice('Хяналтын хугацаа','code',REG_POST)}${regField('Хяналтын өдөр','date',today(),'date',true)}${regText('Эхэд харагдах зөвлөгөө','advice')}${regText('Эмчийн дотоод үзлэгийн тэмдэглэл','note')}${regSubmit('Төрсний дараах үзлэг хадгалах')}</form>`:''}</div></div>`}
function regTrainingTab(p){regG(p);return `${regTitle('Жирэмсний үеийн бүлгийн сургалт','Хавсралт 5 · гурван гурван сард сургалт, ирцийн бүртгэл.')}<div class="rg-train-grid">${REG_TRAINING.map((t,i)=>{const rec=p.trainingPublic.filter(x=>x.index===i).slice(-1)[0];return `<div class="rg-box"><h3>${h(t.label)}</h3>${t.topics.map(x=>`<p class="rg-training-line">✓ ${h(x)}</p>`).join('')}${rec?regTag('Хамрагдсан · '+pretty(rec.date),'good'):regTag('Хамрагдаагүй','warn')}</div>`}).join('')}</div><div class="rg-box"><h3>Сургалтын ирц бүртгэх</h3><form id="regTrainingForm" class="rg-form rg-grid">${regChoice('Сургалтын үе','index',REG_TRAINING.map((x,i)=>[String(i),x.label]))}${regField('Сургалтын огноо','date',today(),'date',true)}${regChoice('Хэлбэр','mode',[['class','Танхим'],['online','Цахим']])}${regText('Эхэд харагдах сургалтын товч агуулга','message')}${regSubmit('Сургалтад хамрагдсаныг бүртгэх')}</form></div>`}
function regHub(p){if(!p)return '<div class="rg-box">Эх сонгоогүй байна.</div>';regG(p);const k=state.regTab||'plan';const tabs=[['plan','8 үзлэг'],['risk','Эрсдэл А/Б/В/Г'],['labs','Шинжилгээ'],['screens','Асуумж'],['delivery','Төрсний дараах'],['training','Сургалт']];return `<div class="rg-hub"><div class="rg-nav">${tabs.map(([id,label])=>`<button data-regtab="${id}" class="${k===id?'active':''}" type="button">${label}</button>`).join('')}</div>${({plan:regMilestoneTab,risk:regRiskTab,labs:regLabsTab,screens:regScreenTab,delivery:regDeliveryTab,training:regTrainingTab})[k](p)}<div class="rg-disclaimer">Энэ нь журмын дагуух туршилтын бүртгэл. Мэргэжлийн тусламжийн клиник заавар, хууль ёсны жор, хамгаалагдсан эмнэлгийн мэдээллийн санг орлохгүй. Эмзэг асуумжийн мэдээлэл энэ DEMO-д зөвхөн эмчийн UI дээр харагддаг ч браузерийн локал хадгалалт нь бодит нууцлалын хамгаалалт биш.</div></div>`}
function regReports(){const arr=visible();arr.forEach(regG);const done=arr.reduce((n,p)=>n+p.carePlan.filter(x=>x.status==='complete').length,0),labs=arr.reduce((n,p)=>n+p.labs.filter(x=>x.status!=='reviewed').length,0),post=arr.filter(p=>p.delivery?.date).length,trained=arr.reduce((n,p)=>n+p.trainingPublic.length,0);return `${heading('ЖУРМЫН ГҮЙЦЭТГЭЛ','Хяналтын чанарын тайлан','Хавсралт 2–5: үзлэг, шинжилгээ, эрсдэлийн үнэлгээ, төрөлт, сургалтын биелэлтийн туршилтын тайлан.') }<div class="rg-counters"><div><small>Жирэмсний үзлэгийн checklist</small><b>${done}</b></div><div><small>Шинжилгээ хүлээгдэж буй</small><b>${labs}</b></div><div><small>Төрөлт бүртгэсэн</small><b>${post}</b></div><div><small>Сургалтын ирц</small><b>${trained}</b></div></div><div class="card pad"><h2>Эх бүрийн журмын хэрэгжилт</h2><div class="rg-table-wrap"><table class="rg-table"><thead><tr><th>Эхийн нэр</th><th>Жирэмсний 8 үзлэг</th><th>Шинжилгээ</th><th>Эрсдэлийн асуумж</th><th>Сургалт</th><th>Үйлдэл</th></tr></thead><tbody>${arr.map(p=>`<tr><td><strong>${h(p.name)}</strong><small>${h(p.id)}</small></td><td>${p.carePlan.filter(x=>x.status==='complete').length}/8</td><td>${p.labs.length}</td><td>${clinicalGet(p.id).risk.length}</td><td>${p.trainingPublic.length}/3</td><td>${btn('Хяналт нээх','reg-open','ghost',`data-id="${h(p.id)}"`)}</td></tr>`).join('')}</tbody></table></div></div>`}
/* Attach to existing admin UI and workflows. */
const regOldDetailTab=detailTab;
detailTab=function(p){if(state.detailTab==='protocol')return regHub(p);return regOldDetailTab(p)};
const regOldNewPatientPage=newPatientPage;
newPatientPage=function(){let s=regOldNewPatientPage();if(session.role!=='clinic')return s;const extra=`<section class="card pad form-section"><h2 class="section-title"><span class="index">03</span> Эрсдэлийн үнэлгээ</h2><div class="mini-notice">Хавсралт 3 (хуудас 12–13) · Эмчийн дотоод мэдээлэл. Хуучин A/B/C ангиллаас тусдаа.</div><div class="rg-risk-grids">${Object.entries(REG_RISK).map(([l,items])=>`<section><h3>${l} бүлэг</h3>${items.map((q,i)=>`<label class="rg-risk-item"><input type="checkbox" name="riskFactor" value="${h(l+'|'+i)}"><span>${h(q)}</span></label>`).join('')}</section>`).join('')}</div>${regText('Эрсдэлийн үнэлгээний тайлбар','riskNote')}</section>`;
return s.replace('<section class="card pad form-section"><h2 class="section-title"><span class="index">04</span>',extra+'<section class="card pad form-section"><h2 class="section-title"><span class="index">04</span>')};
const regOldPatientPage=patientPage;
patientPage=function(){const t=regOldPatientPage();return t.replace(/(<button[^>]*data-detail=\"audit\"[^>]*>LOG<\/button>)/, '$1<button type=\"button\" data-detail=\"protocol\" class=\"'+(state.detailTab==='protocol'?'active':'')+'\">Журмын хяналт</button>')};
const regOldPage=page;
page=function(){if(state.view==='protocolReports')return regReports();return regOldPage()};
const regOldNav=navlist;
navlist=function(){return [...regOldNav(),['protocolReports','Журмын тайлан','chart']]};
state.regTab='plan';
function regCollectAnswers(f,prefix,n){return Array.from({length:n},(_,i)=>String(f.get(prefix+i)||''))}
function regHandleSubmit(e){const form=e.target;if(!form.id.startsWith('reg'))return;e.preventDefault();e.stopImmediatePropagation();if(!session)return;const p=getp(state.patientId);if(!p)return;regG(p);const f=new FormData(form),v=k=>String(f.get(k)||'').trim(),c=clinicalGet(p.id),date=v('date')||today();let message='Бүртгэл хадгалагдлаа.';
 if(form.id==='regMilestoneForm'){let index=Number(v('index')),checked=f.getAll('check').map(Number),status=v('status');if(status==='complete'&&checked.length<REG_STEPS[index].list.length){alert('Бүрэн гэж тэмдэглэх бол checklist-ийн бүх мөрийг шалгана уу. Эсвэл “Дутуу” төлөв сонгоно уу.');return;}const data={index,date,status,checked,doctor:session.name,advice:v('advice')};p.carePlan=p.carePlan.filter(x=>x.index!==index);p.carePlan.push(data);c.milestones.push({...data,note:v('note')});message='Хяналтын үзлэгийн checklist шинэчлэгдлээ.';}
 else if(form.id==='regRiskForm'){const factors=f.getAll('riskFactor').map(String);c.risk.push({date,factors,note:v('note'),plan:v('plan'),actor:session.name});message='Эрсдэлийн үнэлгээ эмчийн бүртгэлд хадгалагдлаа.';}
 else if(form.id==='regLabForm'){const rec={id:'lab'+id(),date,name:v('name'),status:v('status'),message:v('status')==='reviewed'?v('message'):'',addedBy:session.name};p.labs.push(rec);c.rawLabs.push({id:rec.id,rawResult:v('rawResult'),internalMessage:v('message'),date});message='Шинжилгээний төлөв хадгалагдлаа.';}
 else if(form.id==='regTBForm'||form.id==='regDVForm'){const isTB=form.id==='regTBForm',a=regCollectAnswers(f,isTB?'tb':'dv',isTB?8:5);if(a.some(x=>!x)){alert('Асуулт бүрт хариулна уу.');return}const positive=a.filter(x=>x==='yes').length;c.screens.push({type:isTB?'tb':'dv',date,answers:a,positive,note:v('note'),actor:session.name});if(positive)message='Эерэг хариу илэрсэн. Мэргэжлийн эмчийн үнэлгээ болон холбогдох арга хэмжээг журмын дагуу хэрэгжүүлнэ үү.';}
 else if(form.id==='regEPDSForm'){const a=regCollectAnswers(f,'ep',10).map(Number);if(a.some(x=>!Number.isFinite(x))){alert('Оноог бөглөнө үү.');return}const score=a.reduce((x,y)=>x+y,0);c.screens.push({type:'epds',date,answers:a,score,positive:score>=11||a[9]>0,note:v('note'),actor:session.name});message=a[9]>0?'Өөрийгөө гэмтээх бодол илэрсэн: яаралтай аюулгүй байдлын үнэлгээ шаардлагатай.':score>=11?'≥11 оноо: мэргэжлийн үнэлгээнд илгээх шаардлагатай.':score>=5&&score<=9?'5–9 оноо: журмын дагуу 1 сарын дараа давтан үнэлнэ.':`Эдинбургийн сорил: ${score}/30. Эмчийн үнэлгээ шаардлагатай.`;}
 else if(form.id==='regDeliveryForm'){p.delivery={date:v('date'),place:v('place'),type:v('type'),message:v('message')};c.deliveryNotes=v('privateNote');message='Төрөлт бүртгэгдлээ. Төрсний дараах 4 хяналт идэвхэжлээ.';}
 else if(form.id==='regPostForm'){if(!p.delivery?.date){alert('Эхлээд төрөлтийн бүртгэл хийнэ.');return;}let rec={code:v('code'),date,advice:v('advice'),author:session.name};p.postpartumFollowups=p.postpartumFollowups.filter(x=>x.code!==rec.code);p.postpartumFollowups.push(rec);c.notes.push({date,kind:'postpartum',code:rec.code,note:v('note')});message='Төрсний дараах хяналт хадгалагдлаа.';}
 else if(form.id==='regTrainingForm'){const x={index:Number(v('index')),date,mode:v('mode'),message:v('message')};p.trainingPublic=p.trainingPublic.filter(r=>r.index!==x.index);p.trainingPublic.push(x);message='Бүлгийн сургалтын хамрагдалт хадгалагдлаа.';}
 else return;regAudit('Журмын хяналт · '+form.id,p.id);render();toast(message);
}
